import{_ as a,a as p}from"./chunks/mmad_hf32_950.DFizjsQ4.js";import{_ as n,o as c,a as e,b as t}from"./app.CIoiBgkh.js";const A=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"SIMD API","link":"/api/SIMD-API/SIMD-API"},{"text":"C API","link":"/api/SIMD-API/c_api/README"},{"text":"矩阵计算","link":"/api/SIMD-API/c_api/cube_compute/cube_compute"},{"text":"矩阵计算关键特性说明","link":"/api/SIMD-API/c_api/cube_compute/mmad_compute_key_features/mmad_compute_key_features"},{"text":"HF32","link":"/api/SIMD-API/c_api/cube_compute/mmad_compute_key_features/HF32"}]},"headers":[],"relativePath":"api/SIMD-API/c_api/cube_compute/mmad_compute_key_features/HF32.md","filePath":"api/SIMD-API/c_api/cube_compute/mmad_compute_key_features/HF32.md","lastUpdated":1789956443000}'),_={name:"api/SIMD-API/c_api/cube_compute/mmad_compute_key_features/HF32.md"};function l(i,s,d,o,m,r){return c(),e("div",null,[...s[0]||(s[0]=[t('<div><article class="markdown-body"><h1>HF32</h1><p><strong>特性说明：</strong></p><p>HF32的核心功能体现为：用户在输入矩阵A、B矩阵都为fp32数据类型的场景下，当配置开启HF32开关后，fp32数据在执行矩阵乘法运算前会被转换并舍入为HF32（half-fp32）格式。这种做法可使Mmad类（f322f32）接口的计算性能得到提升，但会带来一定的精度损失。需要注意的是，尽管中间计算使用HF32格式，最终的运算结果仍以fp32格式输出，以保证后续处理的兼容性。</p><p>开启HF32对性能的影响如下：</p><div data-filter="A3,910b"><ul><li><p>针对如下产品型号：</p><div data-filter="A3"><p>Atlas A3系列产品</p></div><div data-filter="910b"><p>Atlas A2系列产品</p></div><p>开启HF32可使Mmad类（f322f32）接口的计算性能提升至原来的两倍。</p></li></ul></div><div data-filter="950"><ul><li>针对Ascend 950PR&amp;950DT系列产品产品，开启HF32可使Mmad（f322f32）接口的计算性能提升至原来的八倍。</li></ul></div><p>舍入模式说明：fp32至HF32转换过程中的舍入模式由<a href="../asc_set_hf32_round_mode.html">asc_set_hf32_round_mode</a>接口配置。当HF32模式开启且设置asc_hf32_round_mode为NEAREST_AWAY时，FP32将以向最接近的值舍入，平局时远离零的方式舍入为HF32；若设置asc_hf32_round_mode为NEAREST_EVEN时，FP32将以向最接近的值舍入，平局时向偶数舍入的方式舍入为HF32。</p><div data-filter="910b,A3"><p><strong>图1</strong> HF32数值精度示意图<a id="zh_cn_topic_mmad_keyfunc_section1_figure1"></a></p><p><img src="'+a+'" alt="HF32数值精度示意图" title="HF32数值精度示意图"></p></div><div data-filter="950"><p>注意，针对Ascend 950PR&amp;950DT系列产品产品，其HF32格式的尾数位为10位，示意图如图2所示：</p><p><strong>图2</strong> Ascend 950PR&amp;950DT系列产品产品HF32数值精度示意图<a id="zh_cn_topic_mmad_keyfunc_section1_figure2"></a></p><p><img src="'+p+`" alt="Ascend 950PR&amp;950DT系列产品产品HF32数值精度示意图" title="Ascend 950PR&amp;950DT系列产品产品HF32数值精度示意图"></p></div><p><strong>使用示例：</strong></p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="c1">// 开启HF32模式</span>
<span class="n">asc_enable_hf32</span><span class="p">();</span>
<span class="n">asc_set_hf32_round_mode</span><span class="p">(</span><span class="n">asc_hf32_round_mode</span><span class="o">::</span><span class="n">NEAREST_AWAY</span><span class="p">);</span>
<span class="n">asc_mmad</span><span class="p">(</span><span class="n">c</span><span class="p">,</span><span class="w"> </span><span class="n">a</span><span class="p">,</span><span class="w"> </span><span class="n">b</span><span class="p">,</span><span class="w"> </span><span class="n">m</span><span class="p">,</span><span class="w"> </span><span class="n">k</span><span class="p">,</span><span class="w"> </span><span class="n">n</span><span class="p">,</span><span class="w"> </span><span class="n">asc_unit_flag_mode</span><span class="o">::</span><span class="n">DISABLE</span><span class="p">,</span>
<span class="w">         </span><span class="nb">false</span><span class="p">,</span><span class="w"> </span><span class="nb">false</span><span class="p">,</span><span class="w"> </span><span class="nb">true</span><span class="p">);</span>
<span class="c1">// 关闭HF32模式并恢复舍入模式默认值</span>
<span class="n">asc_disable_hf32</span><span class="p">();</span>
<span class="n">asc_set_hf32_round_mode</span><span class="p">(</span><span class="n">asc_hf32_round_mode</span><span class="o">::</span><span class="n">NEAREST_EVEN</span><span class="p">);</span>
</code></pre></div></article></div>`,1)])])}const h=n(_,[["render",l]]);export{A as __pageData,h as default};
